/* SPDX-License-Identifier: Apache-2.0 */

#include <zephyr/kernel.h>
#include <zephyr/device.h>
#include <zephyr/drivers/adc.h>
#include <zephyr/sys/util.h>
#include <zephyr/logging/log.h>

LOG_MODULE_REGISTER(adc_example, LOG_LEVEL_INF);

#define ADC_RESOLUTION      12
#define ADC_OVERSAMPLING    4      /* 2^4 = 16 samples averaged */
#define ADC_CHANNEL_ID      0
#define ADC_BUFFER_SIZE     1

/* Buffer that will hold the ADC sample(s) */
static int16_t adc_sample_buffer[ADC_BUFFER_SIZE];

void main(void)
{
    const struct device *adc_dev = DEVICE_DT_GET(DT_ALIAS(adc0));

    if (!device_is_ready(adc_dev)) {
        LOG_ERR("ADC device not ready");
        return;
    }

    /* Configure the ADC channel */
    struct adc_channel_cfg channel_cfg = {
        .gain             = ADC_GAIN_1,
        .reference        = ADC_REF_INTERNAL,
        .acquisition_time = ADC_ACQ_TIME_DEFAULT,
        .channel_id       = ADC_CHANNEL_ID,
#if defined(CONFIG_ADC_NRFX_SAADC)
        .input_positive   = NRF_SAADC_INPUT_AIN0,  /* adjust if needed */
#endif
    };

    int ret = adc_channel_setup(adc_dev, &channel_cfg);
    if (ret) {
        LOG_ERR("Failed to setup ADC channel (err %d)", ret);
        return;
    }

    /* Define the ADC read sequence */
    struct adc_sequence sequence = {
        .channels    = BIT(ADC_CHANNEL_ID),
        .buffer      = adc_sample_buffer,
        .buffer_size = sizeof(adc_sample_buffer),
        .resolution  = ADC_RESOLUTION,
        .oversampling = ADC_OVERSAMPLING,
    };

    LOG_INF("Starting ADC read loop");

    while (1) {
        ret = adc_read(adc_dev, &sequence);
        if (ret == 0) {
            LOG_INF("ADC raw sample: %d", adc_sample_buffer[0]);
        } else {
            LOG_ERR("ADC read error: %d", ret);
        }

        k_sleep(K_SECONDS(1));
    }
}
